function renderBStocks(){const rows=bstocks;$('#bstocks-count').textContent=rows.length;$('#bstocks-record-count').textContent=`${rows.length} listed`;$('#bstocks-heading').textContent=`All catalog-listed bStocks · ${rows.length}`;if(!rows.length){$('#bstocks-list').innerHTML='<div class="empty-state"><b>No bStocks were returned by the live catalog.</b>Check the Binance RWA feed status and refresh the catalog.</div>';return}$('#bstocks-list').innerHTML=`<div class="table-head bstocks-row"><span>TICKER</span><span>UNDERLYING</span><span>TOKEN</span><span>CONTRACT</span><span>STATUS</span></div>`+rows.map(x=>`<div class="bstocks-row"><span class="pair-identity">${logoMarkup(x.underlying,x.name)}<button data-symbol="${esc(x.underlying)}">${esc(x.underlying)}</button></span><span>${esc(x.name)}</span><span>${esc(x.symbol)}</span><span class="contract-cell contract">${esc(x.address)}</span><span class="decimals-cell catalog-badge">Listed</span></div>`).join('');bindLogoFallbacks($('#bstocks-list'));document.querySelectorAll('#bstocks-list [data-symbol]').forEach(b=>b.onclick=()=>setActiveAsset(b.dataset.symbol))}
function renderBstocksNews(){const query=$('#news-search').value.trim().toLowerCase(),filter=$('#news-filter').value,sourceFilter=$('#news-source-filter')?.value||'all',rows=bstocksNews.filter(x=>(filter==='all'||x.sentiment===filter)&&(!query||`${x.underlying} ${x.name} ${x.tokenSymbol}`.toLowerCase().includes(query))&&(sourceFilter==='all'||(x.sourceCoverage||[]).some(s=>s.name===sourceFilter&&s.status==='ok'&&s.count>0)));$('#news-count').textContent=bstocksNews.length||'—';$('#news-heading').textContent=`Coverage · ${rows.length} of ${bstocksNews.length} underlyings`;if(!rows.length){$('#bstocks-news-list').innerHTML='<div class="empty-state">No bStocks match the current filter.</div>';return}$('#bstocks-news-list').innerHTML=`<div class="news-table-head"><span>ASSET</span><span>SENTIMENT</span><span>RECENT HEADLINES</span></div>`+rows.map(x=>{const label=x.sentiment==='unknown'?'NO COVERAGE':x.sentiment.toUpperCase(),items=x.headlines.filter(n=>n.fresh).map(n=>{let link='';try{const u=new URL(n.link);if(u.protocol==='https:')link=` href="${esc(u.href)}" target="_blank" rel="noopener noreferrer"`}catch{}return`<a class="news-item"${link}><b>${esc(n.title)}</b><small>${esc(n.source||'News feed')} · ${esc(n.publishedAt||'time unavailable')}</small></a>`}).join(''),used=(x.sourceCoverage||[]).filter(s=>s.status==='ok'&&s.count>0).map(s=>s.name);return`<div class="news-row"><span class="pair-identity">${logoMarkup(x.underlying,x.name)}<span><button class="news-ticker" data-symbol="${esc(x.underlying)}">${esc(x.underlying)}</button><small>${esc(x.name)} · ${esc(x.tokenSymbol)}</small></span></span><span><i class="news-badge ${esc(x.sentiment)}">${label}</i><small>${x.freshHeadlineCount?`${x.bullishCount} bullish · ${x.bearishCount} bearish headlines`:x.coverage==='error'?'Feed unavailable':'No recent matched headlines'}</small><small>${used.length?`${used.length} source${used.length===1?'':'s'}: ${esc(used.join(', '))}`:'No source returned a matched headline'}</small></span><span class="news-items">${items||'<span class="news-empty">No recent, ticker-matched headlines found.</span>'}</span></div>`}).join('');bindLogoFallbacks($('#bstocks-news-list'));$('#bstocks-news-list').querySelectorAll('[data-symbol]').forEach(b=>b.onclick=()=>setActiveAsset(b.dataset.symbol))}
function setNewsSourceOptions(providers=[]){const select=$('#news-source-filter');if(!select)return;const previous=select.value, names=[...new Set(providers.map(p=>typeof p==='string'?p:p.name).filter(Boolean))];select.innerHTML='<option value="all">All sources</option>'+names.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');if(names.includes(previous))select.value=previous}
async function loadBstocksNews(refresh=false){
 const root=$('#bstocks-news-list');
 if(dashboardDemoMode){
  const examples={NVDA:['bullish','Positive catalyst wording'],TSLA:['bearish','Negative catalyst wording'],QQQ:['neutral','Mixed catalyst wording']};
  bstocksNews=bstocks.map(listing=>{
   const symbol=listing.underlying,example=examples[symbol],sentiment=example?.[0]||'unknown';
   return{underlying:symbol,name:listing.name||symbol,tokenSymbol:listing.symbol||listing.tokenSymbol||symbol,sentiment,coverage:example?'demo-example':'demo-no-fixture',score:sentiment==='bullish'?1:sentiment==='bearish'?-1:0,bullishCount:sentiment==='bullish'?1:0,bearishCount:sentiment==='bearish'?1:0,freshHeadlineCount:example?1:0,sourceCoverage:[{name:'Demo fixtures',status:'ok',count:example?1:0}],headlines:example?[{title:`DEMO EXAMPLE — ${example[1]} for ${symbol}; synthetic text, not current news`,source:'PulseLayer demo fixture',publishedAt:'Demo sample',fresh:true,link:''}]:[]};
  });
  setNewsSourceOptions(['Demo fixtures']);$('#news-routes').innerHTML='<div class="news-route"><span>Dashboard demo</span><b>SIMULATED</b><small>Only local sample headlines; live API routes are not called.</small></div>';$('#news-count').textContent=bstocksNews.length;
  $('#news-updated').textContent=`Demo fixtures · ${bstocksNews.length} bStocks tickers covered; only NVDA, TSLA, and QQQ have synthetic examples`;
  $('#news-summary').innerHTML=`<div class="signal-card"><span>bStocks tickers covered</span><b>${bstocksNews.length}</b><small>Full catalog from the bStocks API</small></div><div class="signal-card"><span>Sample sentiment examples</span><b>${Object.keys(examples).filter(symbol=>bstocks.some(x=>x.underlying===symbol)).length}</b><small>Synthetic, not live headlines</small></div><div class="signal-card"><span>Other headlines</span><b>${Math.max(0,bstocksNews.length-3)}</b><small>No local fixture · not queried</small></div>`;
  renderBstocksNews();return;
 }
 try{
  root.innerHTML='<div class="empty-state"><b>Loading headlines for every listed bStocks ticker…</b>Each catalog ticker is checked individually against matching company and symbol headlines.</div>';
  const body=await getPaidJson(`/api/v1/bstocks/news${refresh?'?refresh=1':''}`),data=body.data;
  bstocksNews=data.listings||[];const s=data.summary||{};setNewsSourceOptions(data.providers||[]);const connected=(data.providers||[]).filter(p=>p.active).length,configured=(data.providers||[]).filter(p=>p.configured).length;
  $('#news-summary').innerHTML=`<div class="signal-card"><span>bStocks tickers covered</span><b>${data.count??bstocksNews.length}</b><small>Current Binance bStocks catalog</small></div><div class="signal-card"><span>Bullish</span><b class="up">${s.bullish||0}</b><small>Recent positive catalyst headlines</small></div><div class="signal-card"><span>Bearish</span><b class="down">${s.bearish||0}</b><small>Recent negative catalyst headlines</small></div><div class="signal-card"><span>News routes active</span><b>${connected} / ${(data.providers||[]).length}</b><small>${configured} configured · route totals count ticker-matched headlines</small></div><div class="signal-card"><span>Neutral / no coverage</span><b>${(s.neutral||0)+(s.noCoverage||0)}</b><small>${s.neutral||0} neutral · ${s.noCoverage||0} without recent headlines</small></div>`;
  $('#news-routes').innerHTML=(data.providers||[]).map(p=>{const status=p.active?'CONNECTED':p.configured?'UNAVAILABLE':'KEY REQUIRED';return`<div class="news-route"><span>${esc(p.name)}</span><b class="${p.active?'route-up':p.configured?'route-down':'route-muted'}">${status}</b><small>${p.active?`${p.articles} matched headlines across covered tickers`:p.configured?'Configured, but no successful response':'Add credentials to .env to enable'}</small></div>`}).join('');
  $('#bstocks-news-list').dataset.asof=data.asOf||'';
  $('#news-updated').textContent=`${data.source||'News feed'} · Updated ${data.asOf?new Date(data.asOf).toLocaleString():'—'} · ${data.freshnessHours||72}h freshness window`;
  renderBstocksNews();
 }catch(e){
  const locked=e.status===402||health.payments?.status==='setup-required';
  $('#news-count').textContent=locked?'locked':'—';
  $('#news-updated').textContent=locked?'Paid news pack · B402 merchant setup required':'News source unavailable';
  $('#news-summary').innerHTML=`<div class="empty-state"><b>${locked?'Headline sentiment is locked until B402 is configured.':'Headline source is unavailable.'}</b>News coverage is built from every ticker in the Binance bStocks catalog. This deployment has no active B402 merchant configuration, so paid headlines cannot load yet.</div>`;
  root.innerHTML=`<div class="empty-state"><b>${locked?'The paid news pack returned 402.':'Could not load bStocks news.'}</b>${esc(e.message)}</div>`;
 }
}
async function init(){
 initWallet();const walletModal=$('#wallet-modal'),walletStatus=$('#wallet-modal-status');
 $('#wallet-connect').onclick=()=>{if(walletAddress){walletAddress='';walletProvider=null;localStorage.removeItem('pulselayer-wallet-session');updateWalletUi();updateQuoteStatus('Wallet disconnected from this page.')}else{walletStatus.textContent='';walletModal.showModal()}};
 const connectChoice=async kind=>{walletStatus.textContent=kind==='binance'?'Opening Binance Wallet…':'Opening your browser wallet…';try{await connectBnbWallet(true,kind);walletModal.close();walletStatus.textContent='';updateQuoteStatus(`Wallet connected on BNB Smart Chain: ${walletShort(walletAddress)}.`)}catch(error){walletStatus.textContent=error.message}};
 $('#connect-binance-wallet').onclick=()=>connectChoice('binance');$('#connect-injected-wallet').onclick=()=>connectChoice('other');
 $('#dashboard-demo-toggle').onclick=toggleDashboardDemoMode;
 document.querySelectorAll('.nav[data-view]').forEach(b=>b.onclick=()=>{setView(b.dataset.view);if(b.dataset.scroll)document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});if(b.dataset.view==='agent-calls')renderAgentLog();if(b.dataset.view==='dislocations')renderDislocationTable();if(b.dataset.view==='news'&&!bstocksNews.length)loadBstocksNews()});
 $('#refresh-news').onclick=()=>loadBstocksNews(true);$('#replay-quote-pack').onclick=loadPaidQuotePack;
 $('#dislocation-filter').onchange=event=>{dislocationFilter=event.target.value;renderDislocationTable()};
 $('#dislocation-search').onclick=()=>{dislocationQuery=$('#dislocation-search-input').value.trim();renderDislocationTable()};
 $('#dislocation-search-input').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();$('#dislocation-search').click()}};
 $('#news-search').oninput=renderBstocksNews;$('#news-filter').onchange=renderBstocksNews;$('#news-source-filter').onchange=renderBstocksNews;
 try{
  const [catalog,h,b]=await Promise.all([getJson('/api/v1/assets'),getJson('/health'),getJson('/api/v1/issuers/bstocks')]);
  assets=catalog.assets||[];health=h;bstocks=b.listings||[];renderPayment();updateDashboardDemoUi();populateAssetOptions();renderBStocks();renderAgentLog();
  $('#asset-select').onchange=event=>{setSelectLogo('#asset-select-logo',event.target.value);loadAndDraw(event.target.value)};
  const tracked=['NVDA','TSLA','QQQ'].filter(s=>assets.some(a=>a.symbol===s));coreStates=await Promise.all(tracked.map(getDisplayState));
  $('#coverage-line').textContent=`${tracked.length} in focus, ${bstocks.length} bStocks listed, Ondo and xStocks joined where the contract is known.`;
  renderCards(coreStates);renderDislocationTable();renderInstrumentMaster();renderFinanceState();renderEventClock();
  if(coreStates.length)draw(coreStates[0]);else $('#venues').innerHTML='<div class="empty-state"><b>No price data is available from the connected sources.</b>Instrument listings remain visible; refresh when a price source recovers.</div>';
  $('#bstocks-updated').textContent=b.catalogStatus?.live?`${catalog.count} ASSETS · LIVE CATALOG`:'STATIC CORE · CATALOG OFFLINE';
  if(dashboardDemoMode)loadBstocksNews();renderAgentLog()
 }catch(error){$('#payment-status').textContent='Service unavailable';$('#payment-sidebar').textContent='Could not reach API';$('#cards').innerHTML=`<div class="empty-state"><b>PulseLayer could not load the catalog.</b>${esc(error.message)}</div>`;$('#bstocks-list').innerHTML=`<div class="empty-state">${esc(error.message)}</div>`}
}
init();setInterval(async()=>{stateCache.clear();if(!coreStates.length)return;coreStates=await Promise.all(coreStates.map(s=>getDisplayState(s.symbol)));renderCards(coreStates);renderDislocationTable();const selected=$('#asset-select').value;if(selected&&coreStates.some(s=>s.symbol===selected))draw(coreStates.find(s=>s.symbol===selected))},30000);
